"""
    if metadata_exists:
        try:
            with open(metadata_path) as f:
                md=f.read()
            out+=f"```\n{md}\n```\n\n"
        except Exception as e:
            out+=f"Could not read contents of '{metadata_path}': {e}\n\n"
    else:
        out+=f"Could not read contents of '{metadata_path}': No such file or directory (os error 2).\n\n"
    out+=f"""#### Custom assets

"""
    if os.path.exists(cache_dir) and os.listdir(cache_dir):
        out+=f"Cache dir {cache_dir} exists with files\n\n"
