    if pargs.list_themes:
        print("\n".join(THEMES_LIST)); sys.exit(0)
    if pargs.list_languages:
        if LANGS_CONTENT:
            sys.stdout.write(LANGS_CONTENT)
            if not LANGS_CONTENT.endswith("\n"): sys.stdout.write("\n")
        else:
            print("Python:py\nRust:rs\n")
        sys.exit(0)
    if pargs.completion:
        if pargs.completion=="bash":
            sys.stdout.write(COMP_BASH)
            if not COMP_BASH.endswith("\n"): sys.stdout.write("\n")
        elif pargs.completion=="fish":
            sys.stdout.write(COMP_FISH)
            if not COMP_FISH.endswith("\n"): sys.stdout.write("\n")
        elif pargs.completion=="zsh":
            sys.stdout.write(COMP_ZSH)
            if not COMP_ZSH.endswith("\n"): sys.stdout.write("\n")
        elif pargs.completion=="ps1":
            sys.stdout.write(COMP_PS1)
            if not COMP_PS1.endswith("\n"): sys.stdout.write("\n")
        sys.exit(0)
    if pargs.acknowledgements:
        if ACK_CONTENT:
            sys.stdout.write(ACK_CONTENT)
            if not ACK_CONTENT.endswith("\n"): sys.stdout.write("\n")
        else:
            print("Acknowledgements not available")
        sys.exit(0)
    if pargs.diagnostic:
        diag=generate_diagnostic(sys.argv)
        sys.stdout.write(diag)
        if not diag.endswith("\n"): sys.stdout.write("\n")
        sys.exit(0)
    if pargs.cache_subcommand=="cache":
        if pargs.cache_build:
            target=pargs.cache_target or get_cache_dir_path()
            os.makedirs(target, exist_ok=True)
            print(f"Cache built at {target}")
            sys.exit(0)
        if pargs.cache_clear:
            target=pargs.cache_target or get_cache_dir_path()
            try:
                import shutil
                if os.path.exists(target):
                    shutil.rmtree(target)
                print(f"Cache cleared {target}")
            except Exception as e:
                eprint_error(str(e)); sys.exit(1)
            sys.exit(0)
        sys.exit(0)

    def extract_styles_from_args(arg_list):
        vals=[]
        i=0
        while i<len(arg_list):
            tok=arg_list[i]
            if tok=="--style":
                if i+1<len(arg_list): vals.append(arg_list[i+1]); i+=2
                else: i+=1
            elif tok.startswith("--style="):
                vals.append(tok.split("=",1)[1]); i+=1
            elif tok=="-p" or (tok.startswith("-") and not tok.startswith("--") and "p" in tok):
                cnt=tok.count('p') if tok.startswith("-") and not tok.startswith("--") else 1
                for _ in range(cnt if tok!="--plain" else 1):
                    if tok=="-p" or "p" in tok:
                        vals.append("plain")
                i+=1
            elif tok in ("-n","--number") or (tok.startswith("-") and not tok.startswith("--") and "n" in tok):
                vals.append("numbers"); i+=1
            else:
                i+=1
        return vals

    config_style_vals=extract_styles_from_args(config_args) if not no_config else []
    bat_style_env=os.environ.get("BAT_STYLE")
    bat_opts_styles=extract_styles_from_args(bat_opts)
    actual_styles=extract_styles_from_args(actual_argv)

    style_sources=[]
    style_sources.extend(config_style_vals)
    if bat_style_env:
        style_sources.append(bat_style_env)
    style_sources.extend(bat_opts_styles)
    style_sources.extend(actual_styles)

    try:
        final_style=parse_style_list(style_sources)
    except SystemExit:
        raise
    except Exception as e:
        eprint_error(str(e)); sys.exit(1)

    has_auto=False
    for src in style_sources:
        for part in src.split(","):
            if part.strip()=="auto":
                has_auto=True
                break

    decorations_opt=pargs.decorations
    show_decorations=False
    if decorations_opt=="always": show_decorations=True
    elif decorations_opt=="never": show_decorations=False
    else: show_decorations=is_stdout_tty

    if not style_sources:
        if not show_decorations:
            final_style=[]
    else:
        if has_auto and not show_decorations:
            final_style=[]
        if not show_decorations:
            final_style=[]

    if pargs.unbuffered and "numbers" in final_style:
        final_style=[c for c in final_style if c!="numbers"]

    tab_width=4
    env_tabs=os.environ.get("BAT_TABS")
    if env_tabs is not None:
        try: tab_width=int(env_tabs)
        except: pass
    if pargs.tabs is not None:
        tab_width=pargs.tabs

    wrap_mode=pargs.wrap
    if pargs.chop_long_lines:
        wrap_mode="never"

    term_width_raw=pargs.terminal_width
    if term_width_raw is None:
        term_width_raw=os.environ.get("BAT_WIDTH")
    def get_term_width():
        if term_width_raw is None:
            try: return shutil.get_terminal_size().columns
            except: return 80
        else:
            raw=str(term_width_raw)
            try:
                if raw.startswith("+") or raw.startswith("-"):
                    try: cols=shutil.get_terminal_size().columns
                    except: cols=80
                    offset=int(raw)
                    return max(1, cols+offset)
                else:
                    return int(raw)
            except:
                try: return shutil.get_terminal_size().columns
                except: return 80
    terminal_width=get_term_width()

    squeeze_blank=pargs.squeeze_blank
    if pargs.squeeze_limit is not None:
        squeeze_blank=True
        squeeze_limit=pargs.squeeze_limit
    else:
        squeeze_limit=1 if squeeze_blank else None

    color_opt=pargs.color
    use_color=False
    if color_opt=="always": use_color=True
    elif color_opt=="auto": use_color=is_stdout_tty

    input_files=pargs.files
    if not input_files:
        input_files=["-"]

    if pargs.file_names:
        if len(pargs.file_names)!=len(input_files):
            eprint_error("Must be one file name per input type.")
            sys.exit(1)

    has_error=False
    if "rule" in final_style and "grid" in final_style:
        eprint_warning("Style 'rule' is a subset of style 'grid', 'rule' will not be visible.")

    for file_idx, fpath in enumerate(input_files):
        disp_name=pargs.file_names[file_idx] if pargs.file_names else ("STDIN" if fpath=="-" else fpath)
        is_stdin = (fpath=="-")
        data=None
        try:
            if is_stdin:
                data=sys.stdin.buffer.read()
            else:
                if not os.path.exists(fpath):
                    eprint_error(f"'{fpath}': No such file or directory (os error 2)")
                    has_error=True
                    continue
                if os.path.isdir(fpath):
                    eprint_error(f"'{fpath}' is a directory.")
                    has_error=True
                    continue
                with open(fpath,'rb') as ff:
                    data=ff.read()
        except Exception as e:
            eprint_error(f"'{fpath}': {e}")
            has_error=True
            continue
        if data is None:
            data=b""
        contains_null=b'\x00' in data
        if contains_null and not pargs.show_all and pargs.binary=="no-printing":
            continue
        try:
            text=data.decode('utf-8')
        except:
            text=data.decode('utf-8', errors='replace')

        if pargs.strip_ansi=="always":
            text=strip_ansi(text)
        elif pargs.strip_ansi=="auto":
            lang=pargs.language
            if lang and lang.lower()!="plain":
                text=strip_ansi(text)

        lines_raw=text.splitlines()
        total_lines=len(lines_raw)
        original_numbers=list(range(1,total_lines+1))

        if squeeze_blank:
            new_lines=[]
            new_numbers=[]
            consec=0
            limit=squeeze_limit if squeeze_limit is not None else 1
            for content, num in zip(lines_raw, original_numbers):
                is_empty=content.strip()==""
                if is_empty:
                    consec+=1
                    if consec<=limit:
                        new_lines.append(content)
                        new_numbers.append(num)
                else:
                    consec=0
                    new_lines.append(content)
                    new_numbers.append(num)
            lines_raw=new_lines
            original_numbers=new_numbers
            total_lines=len(lines_raw)

        merged_ranges=None
        expanded_sorted=None
        if pargs.line_ranges:
            merged_ranges, expanded_sorted=parse_line_range_for_file(pargs.line_ranges, total_lines if total_lines>0 else 0)
            if merged_ranges:
                filtered=[]
                filtered_nums=[]
                for content, num in zip(lines_raw, original_numbers):
                    in_range=False
                    for s,e in merged_ranges:
                        if s<=num<=e:
                            in_range=True
                            break
                    if in_range:
                        filtered.append(content)
                        filtered_nums.append(num)
                lines_raw=filtered
                original_numbers=filtered_nums
                total_lines=len(lines_raw)
            else:
                lines_raw=[]
                original_numbers=[]
                total_lines=0

        if not lines_raw and pargs.quiet_empty:
            continue

        hl_ranges=parse_highlight_ranges(pargs.highlight_lines)

        do_expand_tabs=False
        if tab_width!=0:
            if final_style:
                do_expand_tabs=True
            if show_decorations:
                do_expand_tabs=True

        transformed=[]
        for content in lines_raw:
            if pargs.show_all:
                t=show_all_line(content, pargs.nonprintable_notation, tab_width if tab_width!=0 else 4)
                nl_marker="␊" if pargs.nonprintable_notation=="unicode" else "^J"
                t+=nl_marker
                transformed.append(t)
            else:
                if do_expand_tabs:
                    transformed.append(expand_tabs_simple(content, tab_width))
                else:
                    transformed.append(content)

        # Handle wrap=never truncation
        if wrap_mode=="never":
            trunc=[]
            for content, orig_num in zip(transformed, original_numbers):
                if not final_style:
                    avail=terminal_width
                else:
                    left=0
                    if "numbers" in final_style:
                        # number width 4 plus space
                        left+=5
                    if "changes" in final_style:
                        left+=2
                    if "grid" in final_style:
                        left+=2
                    avail=terminal_width-left if terminal_width else None
                if avail is not None and len(content)>avail:
                    trunc.append(content[:avail])
                else:
                    trunc.append(content)
            transformed=trunc

        # Wrap character handling
        physical=[]
        if wrap_mode in ("character","word"):
            for content, orig_num in zip(transformed, original_numbers):
                # Determine available width
                if not final_style:
                    avail=terminal_width
                else:
                    if "numbers" in final_style and "changes" in final_style:
                        left_first=10
                        left_cont=10
                    elif "numbers" in final_style:
                        left_first=8
                        left_cont=8
                    elif "changes" in final_style:
                        left_first=5
                        left_cont=5
                    else:
                        left_first=3 if "grid" in final_style else 0
                        left_cont=left_first
                    avail_first=terminal_width-left_first if terminal_width else None
                    avail_cont=terminal_width-left_cont if terminal_width else None
                if wrap_mode=="character":
                    if avail_first is None or len(content)<=avail_first:
                        physical.append((orig_num, content, False))
                    else:
                        # split
                        first=content[:avail_first]
                        physical.append((orig_num, first, False))
                        rest=content[avail_first:]
                        while rest:
