    if os.path.exists(cache_dir) and os.listdir(cache_dir):
        out+=f"Cache dir {cache_dir} exists with files\n\n"
    else:
        out+=f"'{cache_dir}' not found\n\n"
    out+=f"""#### Detected terminal color scheme

not detected

#### Compile time information

{compile_info}

#### Less version

```
> {pager} --version 
{less_out.strip()}
```

"""
    return out

def main():
    actual_argv=sys.argv[1:]
    no_config = "--no-config" in actual_argv
    config_args=read_config_file(get_config_file_path()) if not no_config else []
    bat_opts=get_bat_opts()
    combined=config_args+bat_opts+actual_argv
    pargs=parse_args_with_tracking(combined)
    is_stdout_tty=sys.stdout.isatty()

    if pargs.version:
        print(VERSION); sys.exit(0)
    if pargs.help_short:
        print(SHORT_HELP, end="" if SHORT_HELP.endswith("\n") else "\n"); sys.exit(0)
    if pargs.help:
        print(LONG_HELP, end="" if LONG_HELP.endswith("\n") else "\n"); sys.exit(0)
    if pargs.config_file:
        print(get_config_file_path()); sys.exit(0)
    if pargs.config_dir:
        print(get_config_dir_path()); sys.exit(0)
    if pargs.cache_dir:
        print(get_cache_dir_path()); sys.exit(0)
    if pargs.generate_config_file:
        cfg_path=get_config_file_path()
        cfg_dir=os.path.dirname(cfg_path)
        os.makedirs(cfg_dir, exist_ok=True)
        default_config="""# This is `bat`s configuration file. Each line either contains a comment or
# a command-line option that you want to pass to `bat` by default. You can
# run `bat --help` to get a list of all possible configuration options.

# Specify desired highlighting theme (e.g. "TwoDark"). Run `bat --list-themes`
# for a list of all available themes
#--theme="TwoDark"

# Enable this to use italic text on the terminal. This is not supported on all
# terminal emulators (like tmux, by default):
#--italic-text=always

# Uncomment the following line to disable automatic paging:
#--paging=never

# Uncomment the following line if you are using less version >= 551 and want to
# enable mouse scrolling support in `bat` when running inside tmux. This might
# disable text selection, unless you press shift.
#--pager="less --RAW-CONTROL-CHARS --quit-if-one-screen --mouse"

# Syntax mappings: map a certain filename pattern to a language.
#   Example 1: use the C++ syntax for Arduino .ino files
#   Example 2: Use ".gitignore"-style highlighting for ".ignore" files
#--map-syntax "*.ino:C++"
#--map-syntax ".ignore:Git Ignore"
"""
        with open(cfg_path,'w',encoding='utf-8') as f:
            f.write(default_config)
        print(f"Success! Config file written to {cfg_path}")
        sys.exit(0)
    if pargs.list_themes:
        print("\n".join(THEMES_LIST)); sys.exit(0)
    if pargs.list_languages:
        if LANGS_CONTENT:
            sys.stdout.write(LANGS_CONTENT)
            if not LANGS_CONTENT.endswith("\n"): sys.stdout.write("\n")
        else:
            print("Python:py\nRust:rs\n")
        sys.exit(0)
    if pargs.completion:
        if pargs.completion=="bash":
            sys.stdout.write(COMP_BASH)
            if not COMP_BASH.endswith("\n"): sys.stdout.write("\n")
        elif pargs.completion=="fish":
            sys.stdout.write(COMP_FISH)
            if not COMP_FISH.endswith("\n"): sys.stdout.write("\n")
        elif pargs.completion=="zsh":
            sys.stdout.write(COMP_ZSH)
            if not COMP_ZSH.endswith("\n"): sys.stdout.write("\n")
        elif pargs.completion=="ps1":
            sys.stdout.write(COMP_PS1)
            if not COMP_PS1.endswith("\n"): sys.stdout.write("\n")
        sys.exit(0)
    if pargs.acknowledgements:
        if ACK_CONTENT:
            sys.stdout.write(ACK_CONTENT)
            if not ACK_CONTENT.endswith("\n"): sys.stdout.write("\n")
        else:
            print("Acknowledgements not available")
        sys.exit(0)
    if pargs.diagnostic:
        diag=generate_diagnostic(sys.argv)
        sys.stdout.write(diag)
        if not diag.endswith("\n"): sys.stdout.write("\n")
        sys.exit(0)
    if pargs.cache_subcommand=="cache":
        if pargs.cache_build:
            target=pargs.cache_target or get_cache_dir_path()
            os.makedirs(target, exist_ok=True)
            print(f"Cache built at {target}")
            sys.exit(0)
        if pargs.cache_clear:
            target=pargs.cache_target or get_cache_dir_path()
            try:
                import shutil
                if os.path.exists(target):
                    shutil.rmtree(target)
                print(f"Cache cleared {target}")
            except Exception as e:
                eprint_error(str(e)); sys.exit(1)
            sys.exit(0)
        sys.exit(0)

    def extract_styles_from_args(arg_list):
        vals=[]
        i=0
        while i<len(arg_list):
            tok=arg_list[i]
            if tok=="--style":
                if i+1<len(arg_list): vals.append(arg_list[i+1]); i+=2
                else: i+=1
            elif tok.startswith("--style="):
                vals.append(tok.split("=",1)[1]); i+=1
            elif tok=="-p" or (tok.startswith("-") and not tok.startswith("--") and "p" in tok):
                cnt=tok.count('p') if tok.startswith("-") and not tok.startswith("--") else 1
                for _ in range(cnt if tok!="--plain" else 1):
                    if tok=="-p" or "p" in tok:
                        vals.append("plain")
                i+=1
            elif tok in ("-n","--number") or (tok.startswith("-") and not tok.startswith("--") and "n" in tok):
                vals.append("numbers"); i+=1
            else:
                i+=1
        return vals

    config_style_vals=extract_styles_from_args(config_args) if not no_config else []
    bat_style_env=os.environ.get("BAT_STYLE")
    bat_opts_styles=extract_styles_from_args(bat_opts)
    actual_styles=extract_styles_from_args(actual_argv)

    style_sources=[]
    style_sources.extend(config_style_vals)
    if bat_style_env:
        style_sources.append(bat_style_env)
    style_sources.extend(bat_opts_styles)
    style_sources.extend(actual_styles)

    try:
        final_style=parse_style_list(style_sources)
    except SystemExit:
        raise
    except Exception as e:
        eprint_error(str(e)); sys.exit(1)

    has_auto=False
    for src in style_sources:
        for part in src.split(","):
            if part.strip()=="auto":
                has_auto=True
                break

    decorations_opt=pargs.decorations
    show_decorations=False
    if decorations_opt=="always": show_decorations=True
    elif decorations_opt=="never": show_decorations=False
    else: show_decorations=is_stdout_tty

    if not style_sources:
        if not show_decorations:
            final_style=[]
    else:
        if has_auto and not show_decorations:
            final_style=[]
        if not show_decorations:
            final_style=[]

    if pargs.unbuffered and "numbers" in final_style:
        final_style=[c for c in final_style if c!="numbers"]

    tab_width=4
    env_tabs=os.environ.get("BAT_TABS")
    if env_tabs is not None:
        try: tab_width=int(env_tabs)
        except: pass
    if pargs.tabs is not None:
        tab_width=pargs.tabs

    wrap_mode=pargs.wrap
    if pargs.chop_long_lines:
        wrap_mode="never"

    term_width_raw=pargs.terminal_width
    if term_width_raw is None:
        term_width_raw=os.environ.get("BAT_WIDTH")
    def get_term_width():
        if term_width_raw is None:
            try: return shutil.get_terminal_size().columns
            except: return 80
        else:
            raw=str(term_width_raw)
            try:
                if raw.startswith("+") or raw.startswith("-"):
                    try: cols=shutil.get_terminal_size().columns
                    except: cols=80
                    offset=int(raw)
                    return max(1, cols+offset)
                else:
                    return int(raw)
            except:
                try: return shutil.get_terminal_size().columns
                except: return 80
    terminal_width=get_term_width()

    squeeze_blank=pargs.squeeze_blank
    if pargs.squeeze_limit is not None:
        squeeze_blank=True
        squeeze_limit=pargs.squeeze_limit
    else:
        squeeze_limit=1 if squeeze_blank else None

    color_opt=pargs.color
    use_color=False
    if color_opt=="always": use_color=True
    elif color_opt=="auto": use_color=is_stdout_tty

    input_files=pargs.files
    if not input_files:
        input_files=["-"]

    if pargs.file_names:
        if len(pargs.file_names)!=len(input_files):
            eprint_error("Must be one file name per input type.")
            sys.exit(1)

    has_error=False
    if "rule" in final_style and "grid" in final_style:
        eprint_warning("Style 'rule' is a subset of style 'grid', 'rule' will not be visible.")

    for file_idx, fpath in enumerate(input_files):
        disp_name=pargs.file_names[file_idx] if pargs.file_names else ("STDIN" if fpath=="-" else fpath)
        is_stdin = (fpath=="-")
        data=None
        try:
            if is_stdin:
                data=sys.stdin.buffer.read()
            else:
                if not os.path.exists(fpath):
                    eprint_error(f"'{fpath}': No such file or directory (os error 2)")
                    has_error=True
                    continue
                if os.path.isdir(fpath):
                    eprint_error(f"'{fpath}' is a directory.")
                    has_error=True
                    continue
                with open(fpath,'rb') as ff:
                    data=ff.read()
        except Exception as e:
            eprint_error(f"'{fpath}': {e}")
            has_error=True
            continue
        if data is None:
            data=b""
        contains_null=b'\x00' in data
        if contains_null and not pargs.show_all and pargs.binary=="no-printing":
            continue
        try:
            text=data.decode('utf-8')
        except:
            text=data.decode('utf-8', errors='replace')

        if pargs.strip_ansi=="always":
            text=strip_ansi(text)
        elif pargs.strip_ansi=="auto":
            lang=pargs.language
            if lang and lang.lower()!="plain":
                text=strip_ansi(text)

        lines_raw=text.splitlines()
        total_lines=len(lines_raw)
        original_numbers=list(range(1,total_lines+1))

        if squeeze_blank:
            new_lines=[]
            new_numbers=[]
            consec=0
            limit=squeeze_limit if squeeze_limit is not None else 1
            for content, num in zip(lines_raw, original_numbers):
                is_empty=content.strip()==""
                if is_empty:
                    consec+=1
                    if consec<=limit:
                        new_lines.append(content)
                        new_numbers.append(num)
                else:
                    consec=0
                    new_lines.append(content)
                    new_numbers.append(num)
            lines_raw=new_lines
            original_numbers=new_numbers
            total_lines=len(lines_raw)

        merged_ranges=None
        expanded_sorted=None
        if pargs.line_ranges:
            merged_ranges, expanded_sorted=parse_line_range_for_file(pargs.line_ranges, total_lines if total_lines>0 else 0)
            if merged_ranges:
                filtered=[]
                filtered_nums=[]
                for content, num in zip(lines_raw, original_numbers):
                    in_range=False
                    for s,e in merged_ranges:
                        if s<=num<=e:
                            in_range=True
                            break
                    if in_range:
                        filtered.append(content)
                        filtered_nums.append(num)
                lines_raw=filtered
                original_numbers=filtered_nums
                total_lines=len(lines_raw)
            else:
                lines_raw=[]
                original_numbers=[]
                total_lines=0

        if not lines_raw and pargs.quiet_empty:
            continue

        hl_ranges=parse_highlight_ranges(pargs.highlight_lines)

        do_expand_tabs=False
        if tab_width!=0:
            if final_style:
                do_expand_tabs=True
            if show_decorations:
                do_expand_tabs=True

        transformed=[]
        for content in lines_raw:
            if pargs.show_all:
                t=show_all_line(content, pargs.nonprintable_notation, tab_width if tab_width!=0 else 4)
                nl_marker="␊" if pargs.nonprintable_notation=="unicode" else "^J"
                t+=nl_marker
                transformed.append(t)
            else:
                if do_expand_tabs:
                    transformed.append(expand_tabs_simple(content, tab_width))
                else:
                    transformed.append(content)

        # Handle wrap=never truncation and wrap=character/word only when show_decorations
        if show_decorations:
            if wrap_mode=="never":
                trunc=[]
                for content, orig_num in zip(transformed, original_numbers):
                    if not final_style:
                        avail=terminal_width
                    else:
                        left=0
                        if "numbers" in final_style:
                            left+=5
                        if "changes" in final_style:
                            left+=2
                        if "grid" in final_style:
                            left+=2
                        avail=terminal_width-left if terminal_width else None
                    if avail is not None and len(content)>avail:
                        trunc.append(content[:avail])
                    else:
                        trunc.append(content)
                transformed=trunc

            # Wrap character handling
            physical=[]
            if wrap_mode in ("character","word","auto"):
                # auto treated as character when show_decorations
                effective_wrap = "character" if wrap_mode=="auto" else wrap_mode
                for content, orig_num in zip(transformed, original_numbers):
                    if not final_style:
                        avail_first=terminal_width
                        avail_cont=terminal_width
                    else:
                        if "numbers" in final_style and "changes" in final_style:
                            left_first=10
                            left_cont=10
                        elif "numbers" in final_style:
                            left_first=8
                            left_cont=8
                        elif "changes" in final_style:
                            left_first=5
                            left_cont=5
                        else:
                            left_first=3 if "grid" in final_style else 0
                            left_cont=left_first
                        avail_first=terminal_width-left_first if terminal_width else None
                        avail_cont=terminal_width-left_cont if terminal_width else None
                    if effective_wrap=="character":
                        if avail_first is None or len(content)<=avail_first:
                            physical.append((orig_num, content, False))
                        else:
                            first=content[:avail_first]
                            physical.append((orig_num, first, False))
                            rest=content[avail_first:]
                            while rest:
                                chunk=rest[:avail_cont]
                                physical.append((None, chunk, True))
                                rest=rest[avail_cont:]
                    else: # word
                        if avail_first is None:
                            physical.append((orig_num, content, False))
                        else:
                            words=content.split(' ')
                            cur=""
                            first=True
                            for w in words:
                                check_avail=avail_first if first else avail_cont
                                if len(w)>check_avail:
                                    if cur:
                                        physical.append((orig_num if first else None, cur, not first))
                                        first=False
                                        cur=""
                                    for i in range(0, len(w), check_avail):
                                        chunk=w[i:i+check_avail]
                                        physical.append((orig_num if first else None, chunk, not first))
                                        first=False
                                else:
                                    if len(cur)+(1 if cur else 0)+len(w) <= check_avail:
                                        cur=cur+(" " if cur else "")+w
                                    else:
                                        physical.append((orig_num if first else None, cur, not first))
                                        first=False
                                        cur=w
                            if cur:
                                physical.append((orig_num if first else None, cur, not first))
                transformed=[p[1] for p in physical]
                original_numbers_physical=[p[0] for p in physical]
                is_continuation=[p[2] for p in physical]
            else:
                original_numbers_physical=original_numbers
                is_continuation=[False]*len(transformed)
        else:
            original_numbers_physical=original_numbers
            is_continuation=[False]*len(transformed)

        show_header_filename="header-filename" in final_style or "header" in final_style
        show_header_filesize="header-filesize" in final_style
        show_grid="grid" in final_style
        show_numbers="numbers" in final_style
        show_changes="changes" in final_style
        show_rule="rule" in final_style
        show_snip="snip" in final_style

        change_markers={}
        if show_changes:
            if not is_stdin:
                try:
                    proc = subprocess.run(["git","rev-parse","--show-toplevel"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=os.path.dirname(os.path.abspath(fpath)) if os.path.dirname(fpath) else ".")
                    if proc.returncode==0:
                        toplevel=proc.stdout.decode().strip()
                        rel_path=os.path.relpath(os.path.abspath(fpath), toplevel)
                        proc2=subprocess.run(["git","show",f"HEAD:{rel_path}"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=toplevel)
                        if proc2.returncode==0:
                            head_content=proc2.stdout.decode('utf-8', errors='replace').splitlines()
                            curr_full=text.splitlines()
                            sm=difflib.SequenceMatcher(None, head_content, curr_full)
                            markers_full={}
                            for tag,i1,i2,j1,j2 in sm.get_opcodes():
                                if tag=='equal':
                                    for jj in range(j1,j2):
                                        markers_full[jj+1]=' '
                                elif tag=='replace':
                                    for jj in range(j1,j2):
                                        markers_full[jj+1]='~'
                                elif tag=='insert':
                                    for jj in range(j1,j2):
                                        markers_full[jj+1]='+'
                            for num in original_numbers_physical:
                                if num is not None:
                                    change_markers[num]=markers_full.get(num,' ')
                        else:
                            for num in original_numbers_physical:
                                if num is not None:
                                    change_markers[num]='+'
                    else:
                        for num in original_numbers_physical:
                            if num is not None:
                                change_markers[num]=' '
                except:
                    for num in original_numbers_physical:
                        if num is not None:
                            change_markers[num]=' '
            else:
                for num in original_numbers_physical:
                    if num is not None:
                        change_markers[num]=' '

        file_size=len(data)
        size_str=format_file_size(file_size) if not is_stdin else "-"

        if show_header_filename or show_header_filesize:
            header_lines=[]
            if show_header_filename:
                header_lines.append(f"File: {disp_name}")
            if show_header_filesize:
                header_lines.append(f"Size: {size_str}")
            if show_grid:
                if show_numbers and show_changes:
                    left_dashes=7; right_dashes=terminal_width-left_dashes-1 if terminal_width else 72
                    if right_dashes<0: right_dashes=0
                    top="─"*left_dashes+"┬"+"─"*right_dashes
                elif show_numbers:
                    left_dashes=5; right_dashes=terminal_width-left_dashes-1 if terminal_width else 74
                    if right_dashes<0: right_dashes=0
                    top="─"*left_dashes+"┬"+"─"*right_dashes
                elif show_changes:
                    left_dashes=2; right_dashes=terminal_width-left_dashes-1 if terminal_width else 77
                    if right_dashes<0: right_dashes=0
                    top="─"*left_dashes+"┬"+"─"*right_dashes
                else:
                    top="─"*terminal_width if terminal_width else "─"*80
                print(top)
                if show_numbers and show_changes:
                    left_spaces=" "*7
                    for hl in header_lines:
                        print(f"{left_spaces}│ {hl}")
                    sep="─"*7+"┼"+"─"*(terminal_width-7-1 if terminal_width else 72)
                    print(sep)
                elif show_numbers:
                    left_spaces=" "*5
                    for hl in header_lines:
                        print(f"{left_spaces}│ {hl}")
                    sep="─"*5+"┼"+"─"*(terminal_width-5-1 if terminal_width else 74)
                    print(sep)
                elif show_changes:
                    left_spaces=" "*2
                    for hl in header_lines:
                        print(f"{left_spaces}│ {hl}")
                    sep="─"*2+"┼"+"─"*(terminal_width-2-1 if terminal_width else 77)
                    print(sep)
                else:
                    for hl in header_lines:
                        print(f"{hl}")
                    print("─"*terminal_width if terminal_width else "─"*80)
            else:
                for hl in header_lines:
                    print(hl)
        else:
            if show_grid and not show_header_filename and not show_header_filesize:
                if show_numbers and show_changes:
                    left_dashes=7; right_dashes=terminal_width-left_dashes-1 if terminal_width else 72
                    if right_dashes<0: right_dashes=0
                    print("─"*left_dashes+"┬"+"─"*right_dashes)
                elif show_numbers:
                    left_dashes=5; right_dashes=terminal_width-left_dashes-1 if terminal_width else 74
                    if right_dashes<0: right_dashes=0
                    print("─"*left_dashes+"┬"+"─"*right_dashes)
                elif show_changes:
                    left_dashes=2; right_dashes=terminal_width-left_dashes-1 if terminal_width else 77
                    if right_dashes<0: right_dashes=0
                    print("─"*left_dashes+"┬"+"─"*right_dashes)
                else:
                    print("─"*terminal_width if terminal_width else "─"*80)

        snip_points=set()
        if show_snip and expanded_sorted and len(expanded_sorted)>1:
            for idx in range(len(expanded_sorted)-1):
                cur_end=expanded_sorted[idx][1]
                next_start=expanded_sorted[idx+1][0]
                if next_start>cur_end+1:
                    snip_points.add(cur_end)

        for phys_idx, (orig_num, content) in enumerate(zip(original_numbers_physical, transformed)):
            highlighted=False
            if hl_ranges and orig_num is not None:
                highlighted=is_highlighted(orig_num, hl_ranges)
            out_content=content
            if highlighted and use_color:
                out_content=f"\x1b[48;5;236m{content}\x1b[0m"

            line_out=""
            if show_numbers:
                if orig_num is None:
                    if show_changes:
                        if show_grid:
                            line_out+= " "*7 + "│ " + out_content
                        else:
                            line_out+= " "*7 + out_content
                    else:
                        if show_grid:
                            line_out+= " "*5 + "│ " + out_content
                        else:
                            line_out+= f"{'':>4} {out_content}"
                else:
                    if show_changes:
                        marker=change_markers.get(orig_num,' ')
                        if show_grid:
                            line_out+= f"{orig_num:>4} {marker} │ {out_content}"
                        else:
                            if marker==' ':
                                line_out+= f"{orig_num:>4}   {out_content}"
                            else:
                                line_out+= f"{orig_num:>4} {marker} {out_content}"
                    else:
                        if show_grid:
                            line_out+= f"{orig_num:>4} │ {out_content}"
                        else:
                            line_out+= f"{orig_num:>4} {out_content}"
            else:
                if show_changes:
                    marker=change_markers.get(orig_num,' ') if orig_num is not None else ' '
                    if show_grid:
                        if orig_num is None:
                            line_out+= f"  │ {out_content}"
                        else:
                            if marker==' ':
                                line_out+= f"  │ {out_content}"
                            else:
                                line_out+= f"{marker} │ {out_content}"
                    else:
                        if orig_num is None:
                            line_out+= f"  {out_content}"
                        else:
                            if marker==' ':
                                line_out+= f"  {out_content}"
                            else:
                                line_out+= f"{marker} {out_content}"
                else:
                    line_out+= out_content

            if use_color and show_numbers:
                if show_changes:
                    if show_grid:
                        if orig_num is not None:
                            num_colored=f"\x1b[38;5;246m{orig_num:>4}\x1b[0m"
                            grid_colored="\x1b[38;5;246m│\x1b[0m"
                            marker=change_markers.get(orig_num,' ')
                            line_out=f"{num_colored} {marker} {grid_colored} {out_content}"
                else:
                    if show_grid:
                        if orig_num is not None:
